// Generates the Rust and TypeScript protocol types from omnidm-protocol.schema.json, so
// the extension, the host, the CLI and the app can't drift apart.
//
//   node protocol/generate.mjs           write the generated files
//   node protocol/generate.mjs --check   fail if they are out of date (CI)
//
// Only the subset of JSON Schema the protocol uses is understood: objects with
// `properties`/`required`, string enums, strings, booleans, numbers, integers with a
// `format` (uint16, uint32, uint64, int64), arrays and `$ref`s to `$defs`.

import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const root = join(here, '..');
const schemaPath = join(here, 'omnidm-protocol.schema.json');
const outputs = {
  rust: join(root, 'crates', 'omnidm-ipc', 'src', 'protocol.rs'),
  ts: join(root, 'extension', 'lib', 'protocol.ts'),
};

const schema = JSON.parse(readFileSync(schemaPath, 'utf8'));
const defs = schema.$defs;
const schemaName = relative(root, schemaPath).replaceAll('\\', '/');
const notice = `Generated by protocol/generate.mjs from ${schemaName}. Do not edit.`;

/** The messages: `{ type, payload, direction, description }`, in schema order. */
const messages = schema.oneOf.map((variant) => ({
  type: variant.properties.type.const,
  payload: refName(variant.properties.payload.$ref),
  direction: variant['x-direction'],
  description: variant.description,
}));

function refName(ref) {
  const prefix = '#/$defs/';
  if (!ref?.startsWith(prefix)) throw new Error(`unsupported $ref ${ref}`);
  const name = ref.slice(prefix.length);
  if (!defs[name]) throw new Error(`unknown $ref ${ref}`);
  return name;
}

const isEnum = (def) => def.type === 'string' && Array.isArray(def.enum);
const pascal = (text) => text.replace(/(^|[_-])([a-z])/g, (_, __, c) => c.toUpperCase()).replace(/^[a-z]/, (c) => c.toUpperCase());
const snake = (text) => text.replace(/[A-Z]/g, (c) => `_${c.toLowerCase()}`);
/** A Rust variant name for an enum value: `tooSmall` → `TooSmall`, `GET` → `Get`. */
const variant = (value) => pascal(value === value.toUpperCase() ? value.toLowerCase() : value);

// ---------------------------------------------------------------------------- Rust

const RUST_KEYWORDS = new Set(['type', 'match', 'ref', 'move', 'loop', 'mod', 'use', 'priv', 'static', 'fn', 'impl', 'self', 'super', 'crate', 'where', 'trait', 'struct', 'enum', 'const', 'async', 'await', 'dyn', 'box', 'yield', 'final', 'macro', 'override', 'virtual', 'try']);

function rustType(prop) {
  if (prop.$ref) return refName(prop.$ref);
  switch (prop.type) {
    case 'string':
      return 'String';
    case 'boolean':
      return 'bool';
    case 'number':
      return 'f64';
    case 'integer':
      return { uint16: 'u16', uint32: 'u32', uint64: 'u64', int64: 'i64' }[prop.format] ?? fail(`integer without a known format: ${JSON.stringify(prop)}`);
    case 'array':
      return `Vec<${rustType(prop.items)}>`;
    default:
      return fail(`unsupported property ${JSON.stringify(prop)}`);
  }
}

function rustDoc(text, indent = '') {
  return text ? text.split('\n').map((line) => `${indent}/// ${line}`.trimEnd()).join('\n') + '\n' : '';
}

function rustDef(name, def) {
  let out = rustDoc(def.description);
  if (isEnum(def)) {
    out += '#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]\n';
    out += `pub enum ${name} {\n`;
    for (const value of def.enum) out += `    #[serde(rename = "${value}")]\n    ${variant(value)},\n`;
    out += '}\n\n';
    out += `impl ${name} {\n    /// The name used on the wire.\n    pub fn as_str(self) -> &'static str {\n        match self {\n`;
    for (const value of def.enum) out += `            Self::${variant(value)} => "${value}",\n`;
    out += '        }\n    }\n}\n';
    return out;
  }
  if (def.type !== 'object') fail(`unsupported definition ${name}`);
  const required = new Set(def.required ?? []);
  const props = Object.entries(def.properties ?? {});
  const derives = usesFloat(name) ? 'Debug, Clone, PartialEq' : 'Debug, Clone, PartialEq, Eq';
  out += `#[derive(${derives}, Default, Serialize, Deserialize)]\n#[serde(rename_all = "camelCase")]\n`;
  if (props.length === 0) return out + `pub struct ${name} {}\n`;
  out += `pub struct ${name} {\n`;
  for (const [prop, spec] of props) {
    const field = RUST_KEYWORDS.has(snake(prop)) ? `r#${snake(prop)}` : snake(prop);
    out += rustDoc(spec.description, '    ');
    let type = rustType(spec);
    if (!required.has(prop)) {
      out += '    #[serde(default, skip_serializing_if = "Option::is_none")]\n';
      type = `Option<${type}>`;
    } else if (spec.type === 'array') {
      out += '    #[serde(default)]\n';
    }
    out += `    pub ${field}: ${type},\n`;
  }
  return out + '}\n';
}

/** Whether a definition contains an `f64` anywhere (which rules out `Eq`). */
function usesFloat(name, seen = new Set()) {
  if (seen.has(name)) return false;
  seen.add(name);
  const def = defs[name];
  if (isEnum(def)) return false;
  const check = (spec) => {
    if (spec.$ref) return usesFloat(refName(spec.$ref), seen);
    if (spec.type === 'number') return true;
    if (spec.type === 'array') return check(spec.items);
    return false;
  };
  return Object.values(def.properties ?? {}).some(check);
}

/** Enums can't derive `Default`; give each one its first value. */
function rustEnumDefaults() {
  return Object.entries(defs)
    .filter(([, def]) => isEnum(def))
    .map(([name, def]) => `impl Default for ${name} {\n    fn default() -> Self {\n        Self::${variant(def.enum[0])}\n    }\n}\n`)
    .join('\n');
}

function generateRust() {
  let out = `// SPDX-License-Identifier: GPL-3.0-or-later\n// ${notice}\n\n`;
  out += '//! The protocol messages (docs/omnidm-plan.md §8.2).\n\n';
  out += 'use serde::{Deserialize, Serialize};\n\n';
  out += `/// Envelope version (\`v\`) of every message.\npub const PROTOCOL_VERSION: u32 = ${schema.properties.v.const};\n\n`;
  out += '/// One framed message: the envelope fields plus the message itself.\n';
  out += '#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]\npub struct Envelope {\n';
  out += rustDoc(schema.properties.v.description, '    ') + '    pub v: u32,\n';
  out += rustDoc(schema.properties.id.description, '    ') + '    pub id: String,\n';
  out += rustDoc(schema.properties.re.description, '    ');
  out += '    #[serde(default, skip_serializing_if = "Option::is_none")]\n    pub re: Option<String>,\n';
  out += '    #[serde(flatten)]\n    pub message: Message,\n}\n\n';
  out += '/// Every message type with its payload.\n';
  out += '#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]\n#[serde(tag = "type", content = "payload")]\npub enum Message {\n';
  for (const m of messages) {
    out += rustDoc(`${m.direction}: ${m.description}`, '    ');
    out += `    #[serde(rename = "${m.type}")]\n    ${pascal(m.type)}(${m.payload}),\n`;
  }
  out += '}\n\n';
  out += 'impl Message {\n    /// The message\'s `type` on the wire.\n    pub fn type_name(&self) -> &\'static str {\n        match self {\n';
  for (const m of messages) out += `            Self::${pascal(m.type)}(_) => "${m.type}",\n`;
  out += '        }\n    }\n}\n';
  for (const [name, def] of Object.entries(defs)) out += '\n' + rustDef(name, def);
  out += '\n' + rustEnumDefaults();
  return out;
}

// ---------------------------------------------------------------------- TypeScript

function tsType(prop) {
  if (prop.$ref) return refName(prop.$ref);
  switch (prop.type) {
    case 'string':
      return 'string';
    case 'boolean':
      return 'boolean';
    case 'number':
    case 'integer':
      return 'number';
    case 'array': {
      const item = tsType(prop.items);
      return item.includes(' ') ? `(${item})[]` : `${item}[]`;
    }
    default:
      return fail(`unsupported property ${JSON.stringify(prop)}`);
  }
}

function tsDoc(text, indent = '') {
  if (!text) return '';
  const lines = text.split('\n');
  if (lines.length === 1) return `${indent}/** ${text} */\n`;
  return `${indent}/**\n${lines.map((l) => `${indent} * ${l}`.trimEnd()).join('\n')}\n${indent} */\n`;
}

function tsDef(name, def) {
  let out = tsDoc(def.description);
  if (isEnum(def)) return out + `export type ${name} = ${def.enum.map((v) => `'${v}'`).join(' | ')};\n`;
  const required = new Set(def.required ?? []);
  const props = Object.entries(def.properties ?? {});
  if (props.length === 0) return out + `export type ${name} = Record<string, never>;\n`;
  out += `export interface ${name} {\n`;
  for (const [prop, spec] of props) {
    out += tsDoc(spec.description, '  ');
    out += `  ${prop}${required.has(prop) ? '' : '?'}: ${tsType(spec)};\n`;
  }
  return out + '}\n';
}

function generateTs() {
  let out = `// SPDX-License-Identifier: GPL-3.0-or-later\n// ${notice}\n\n`;
  out += '/* The protocol messages (docs/omnidm-plan.md §8.2). */\n\n';
  out += `/** Envelope version (\`v\`) of every message. */\nexport const PROTOCOL_VERSION = ${schema.properties.v.const};\n\n`;
  out += '/** The payload of each message type. */\nexport interface Payloads {\n';
  for (const m of messages) out += tsDoc(`${m.direction}: ${m.description}`, '  ') + `  ${m.type}: ${m.payload};\n`;
  out += '}\n\n';
  out += 'export type MessageType = keyof Payloads;\n\n';
  out += '/** One message: its type with the matching payload. */\n';
  out += 'export type Message = { [K in MessageType]: { type: K; payload: Payloads[K] } }[MessageType];\n\n';
  out += '/** One framed message: the envelope fields plus the message itself. */\n';
  out += 'export type Envelope = Message & {\n';
  out += tsDoc(schema.properties.v.description, '  ') + '  v: typeof PROTOCOL_VERSION;\n';
  out += tsDoc(schema.properties.id.description, '  ') + '  id: string;\n';
  out += tsDoc(schema.properties.re.description, '  ') + '  re?: string;\n';
  out += '};\n';
  for (const [name, def] of Object.entries(defs)) out += '\n' + tsDef(name, def);
  return out;
}

function fail(message) {
  throw new Error(message);
}

// --------------------------------------------------------------------------- Main

const generated = { [outputs.rust]: generateRust(), [outputs.ts]: generateTs() };
const check = process.argv.includes('--check');
let stale = false;
for (const [path, content] of Object.entries(generated)) {
  let current = null;
  try {
    current = readFileSync(path, 'utf8').replaceAll('\r\n', '\n');
  } catch {
    // Missing: written below, or reported as stale.
  }
  const name = relative(root, path);
  if (current === content) {
    console.log(`up to date: ${name}`);
  } else if (check) {
    console.error(`out of date: ${name} (run: node protocol/generate.mjs)`);
    stale = true;
  } else {
    writeFileSync(path, content);
    console.log(`wrote ${name}`);
  }
}
process.exit(stale ? 1 : 0);
